const ICONS={parties:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7.6 10.2a3.3 3.3 0 1 0 0-6.6 3.3 3.3 0 0 0 0 6.6ZM16.8 9.2a2.7 2.7 0 1 0 0-5.4 2.7 2.7 0 0 0 0 5.4ZM2.8 19.4v-2.2c0-3 2-4.9 4.8-4.9s4.8 1.9 4.8 4.9v2.2M13.1 13.1c.8-.7 1.9-1.1 3.4-1.1 2.8 0 4.7 1.8 4.7 4.6v2.8"/></svg>`,sessions:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6.3 3.7 20 17.4M17.7 3.7 4 17.4M5.1 2.8l2.5 2.5M18.9 2.8l-2.5 2.5M3.2 18.2l2.6 2.6M20.8 18.2l-2.6 2.6"/><path d="m9.5 12 2.5-2.5 2.5 2.5-2.5 2.5L9.5 12Z"/></svg>`,calendar:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5.8h14a2 2 0 0 1 2 2v11H3v-11a2 2 0 0 1 2-2ZM7.2 3v5.2M16.8 3v5.2M3 10.3h18"/></svg>`,journal:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4.3h11.2A2.8 2.8 0 0 1 19 7.1v12.6H7.6A2.6 2.6 0 0 1 5 17.1V4.3Z"/><path d="M7.6 19.7A2.4 2.4 0 0 1 10 17.3h9M9 8h6M9 11.5h6"/></svg>`,arrow:`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h13M14 7l5 5-5 5"/></svg>`};function icon(name){return`<span class="party-icon party-icon-${name}">${ICONS[name]}</span>`}function cleanPrefix(node,prefix){return(node.textContent||'').replace(prefix,'').trim()}function upgradePartyNav(root=document){root.querySelectorAll('[data-nav="parties"] > span').forEach(node=>{if(node.dataset.partyIconReady)return;node.dataset.partyIconReady='true';node.className='nav-party-icon';node.innerHTML=ICONS.parties})}function upgradeMeta(root=document){root.querySelectorAll('.parties-page .campaign-meta, .detail-page .campaign-meta.large').forEach(meta=>{const items=Array.from(meta.children).filter(el=>el instanceof HTMLElement&&!el.classList.contains('meta-separator'));if(items[0]&&!items[0].dataset.partyIconReady){const text=cleanPrefix(items[0],/^\s*♟♟\s*/);items[0].dataset.partyIconReady='true';items[0].innerHTML=`${icon('parties')}<span>${text}</span>`}if(items[1]&&!items[1].dataset.partyIconReady){const text=cleanPrefix(items[1],/^\s*⚔\s*/);items[1].dataset.partyIconReady='true';items[1].innerHTML=`${icon('sessions')}<span>${text}</span>`}if(items[2]&&!items[2].dataset.partyIconReady){const text=items[2].textContent?.trim()||'';items[2].dataset.partyIconReady='true';items[2].innerHTML=`${icon('calendar')}<span>${text}</span>`}})}function upgradeCtas(root=document){root.querySelectorAll('.parties-page .cta, .detail-page .back-link').forEach(control=>{if(control.dataset.partyCtaReady)return;control.dataset.partyCtaReady='true';if(control.classList.contains('back-link'))return;const legacyArrow=Array.from(control.children).find(child=>child.tagName==='SPAN');legacyArrow?.remove();control.insertAdjacentHTML('beforeend',icon('arrow'))})}function upgrade(root=document){upgradePartyNav(root);upgradeMeta(root);upgradeCtas(root)}upgrade();new MutationObserver(records=>{for(const record of records)for(const node of record.addedNodes)if(node instanceof HTMLElement)upgrade(node)}).observe(document.documentElement,{childList:true,subtree:true});